use caesar::{encrypt, decrypt};

#[test]
fn test_encrypt_basic() {
    assert_eq!(encrypt("abc", 1), "bcd");
    assert_eq!(encrypt("xyz", 3), "abc");
    assert_eq!(encrypt("Hello", 13), "Uryyb");
}

#[test]
fn test_encrypt_non_alpha() {
    assert_eq!(encrypt("Hello, World!", 1), "Ifmmp, Xpsme!");
}

#[test]
fn test_decrypt_basic() {
    assert_eq!(decrypt("bcd", 1), "abc");
    assert_eq!(decrypt("Uryyb", 13), "Hello");
}

#[test]
fn test_roundtrip() {
    let text = "The Quick Brown Fox!";
    for shift in [1, 7, 13, 25] {
        assert_eq!(decrypt(&encrypt(text, shift), shift), text);
    }
}

#[test]
fn test_empty() {
    assert_eq!(encrypt("", 5), "");
    assert_eq!(decrypt("", 5), "");
}

